    function list(typeCode) {
        let saved = [];
        try { saved = JSON.parse(localStorage.getItem('masterCategories')) || []; } catch (e) { saved = []; }
        const src = saved.some(c => c.typeCode === typeCode) ? saved : SEED;
        return src.filter(c => c.typeCode === typeCode && c.status === 'Hoạt động');
    }
    function loaiCoQuanList() { return list('DM_57'); }
    function getLoai(code) { return list('DM_57').find(l => l.code === code) || null; }
    function chucVuOf(loaiCode) { return list('DM_58').filter(c => c.parentCode === loaiCode); }
    function chucVuName(code) { const c = list('DM_58').find(x => x.code === code); return c ? c.name : ''; }
